        Assert.Contains(".admin-shell-body .admin-events-page .admin-search-field-input:focus,\n.admin-shell-body .admin-events-page .admin-search-field-input:focus-visible,\n.admin-shell-body .event-participants-page .admin-search-field-input:focus,\n.admin-shell-body .event-participants-page .admin-search-field-input:focus-visible { color: var(--admin-text); background: var(--admin-search); border-color: var(--admin-focus-accent); box-shadow: 0 0 0 0.15rem color-mix(in srgb, var(--admin-focus-accent) 20%, transparent); outline: 0; }", styles);
        Assert.Contains(".admin-shell-body .admin-filter-select:hover { border-color: var(--admin-border); }", styles);
        Assert.DoesNotContain(".admin-shell-body .admin-catalogue-page .admin-filter-select:hover", styles);
        Assert.Contains(".admin-shell-body .admin-catalogue-page .admin-events-state-filter > svg { width: 1rem; height: 1rem; color: var(--admin-muted); }", styles);
        var paletteStart = styles.IndexOf(".admin-shell-body .admin-header,", StringComparison.Ordinal);
        var paletteEnd = styles.IndexOf("}\n.admin-shell-body { --admin-content-gutter", paletteStart, StringComparison.Ordinal);
