        var catalogueStyles = styles[styles.IndexOf("/* Catalogue directory", StringComparison.Ordinal)..];
        foreach (var selector in new[] { ".admin-events-state-chevron {", ".admin-search-field-input {" })
        {
            var start = catalogueStyles.IndexOf(selector, StringComparison.Ordinal);
            if (start < 0) continue;
            var end = catalogueStyles.IndexOf('}', start);
            var rule = catalogueStyles[start..end];
            Assert.DoesNotContain(" color:", rule);
            Assert.DoesNotContain("font-", rule);
        }
        Assert.DoesNotContain(".admin-shell-body .admin-catalogue-page .admin-button-create", catalogueStyles);

        Assert.Contains("loadDirectWorkspace", script);
