        Assert.Contains("clear.hidden = search.value.trim().length === 0", script);
        Assert.Contains("clear?.addEventListener(\"click\", () => { search.value = \"\"; applyFilters(); search.focus(); })", script);
        Assert.DoesNotContain("data-catalogue-filter", script);
        Assert.Contains("data-catalogue-rate-category", script);
        Assert.Contains("data-catalogue-rate-label", script);
        Assert.Contains("category.value === \"Minigame\" ? \"Runs per hour\" : \"Kills per hour\"", script);
    }

    private static string FindRepositoryRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "Bingo.slnx"))) directory = directory.Parent;
        return directory?.FullName ?? throw new InvalidOperationException("Repository root was not found.");
    }
}
